\centering
\includegraphics[width=\columnwidth]{figures/fig_layer_heatmap.pdf}
\caption{Per-layer metric heatmap. Each column: one of five metrics (min-max normalized). Red dashed: CR-composite layer; green dashed: threshold-based layer. CR-composite selections cluster near input layers; threshold-based metrics peak at deep layers.}
\label{fig:layer_heatmap}
\end{figure}

